/* USE : CdMapper.getNmcodeCdList */
SELECT thn.NMCODE_GRP_CD, thn.NMCODE_CD, thn.NMCODE_NM, thn.NMCODE_ITEM_1, thn.NMCODE_ITEM_2, thn.USE_YN FROM TB_HQ_NMCODE thn WHERE thn.HQ_OFFICE_CD = #{hqOfficeCd} AND thn.NMCODE_GRP_CD = #{nmcodeGrpCd}
AND thn.NMCODE_CD LIKE '%'||#{nmcodeCd}||'%'
ORDER BY thn.NMCODE_CD
SELECT tmsn.NMCODE_GRP_CD, tmsn.NMCODE_CD, tmsn.NMCODE_NM, tmsn.NMCODE_ITEM_1, tmsn.NMCODE_ITEM_2, tmsn.USE_YN FROM TB_MS_STORE_NMCODE tmsn WHERE tmsn.STORE_CD = #{storeCd} AND tmsn.NMCODE_GRP_CD = #{nmcodeGrpCd}
AND tmsn.NMCODE_CD LIKE '%'||#{nmcodeCd}||'%'
ORDER BY tmsn.NMCODE_CD

mapper.update:
/* USE : CdMapper.updateNmcodeCdList */



        UPDATE
            TB_HQ_NMCODE
        SET
            NMCODE_NM = #{nmcodeNm,jdbcType=VARCHAR},
            NMCODE_ITEM_1 = #{nmcodeItem1,jdbcType=VARCHAR},
            NMCODE_ITEM_2 = #{nmcodeItem2,jdbcType=VARCHAR},
            USE_YN = #{useYn},
            MOD_DT = #{modDt},
            MOD_ID = #{modId}
        WHERE
            HQ_OFFICE_CD = #{hqOfficeCd}
            AND NMCODE_GRP_CD = #{nmcodeGrpCd}
            AND NMCODE_CD = #{nmcodeCd}



        UPDATE
            TB_MS_STORE_NMCODE
        SET
            NMCODE_NM = #{nmcodeNm,jdbcType=VARCHAR},
            NMCODE_ITEM_1 = #{nmcodeItem1,jdbcType=VARCHAR},
            NMCODE_ITEM_2 = #{nmcodeItem2,jdbcType=VARCHAR},
            USE_YN = #{useYn},
            MOD_DT = #{modDt},
            MOD_ID = #{modId}
        WHERE
            STORE_CD = #{storeCd}
            AND NMCODE_GRP_CD = #{nmcodeGrpCd}
            AND NMCODE_CD = #{nmcodeCd}

mapper.insert:
/* USE : CdMapper.insertNmcodeCdList */
INSERT INTO TB_HQ_NMCODE ( HQ_OFFICE_CD, NMCODE_GRP_CD, NMCODE_CD, PARENT_CD, NMCODE_NM, NMCODE_ITEM_1, NMCODE_ITEM_2, USE_YN, REG_DT, REG_ID, MOD_DT, MOD_ID ) VALUES ( #{hqOfficeCd}, #{nmcodeGrpCd}, #{nmcodeCd}, #{nmcodeGrpCd}, #{nmcodeNm}, #{nmcodeItem1,jdbcType=VARCHAR}, #{nmcodeItem2,jdbcType=VARCHAR}, #{useYn}, #{regDt}, #{regId}, #{modDt}, #{modId} )
INSERT INTO TB_MS_STORE_NMCODE ( STORE_CD, NMCODE_GRP_CD, NMCODE_CD, PARENT_CD, NMCODE_NM, NMCODE_ITEM_1, NMCODE_ITEM_2, USE_YN, REG_DT, REG_ID, MOD_DT, MOD_ID ) VALUES ( #{storeCd}, #{nmcodeGrpCd}, #{nmcodeCd}, #{nmcodeGrpCd}, #{nmcodeNm}, #{nmcodeItem1,jdbcType=VARCHAR}, #{nmcodeItem2,jdbcType=VARCHAR}, #{useYn}, #{regDt}, #{regId}, #{modDt}, #{modId} )

mapper.select:
/* USE : CdMapper.getNmcodeCdDupCnt */



        SELECT  COUNT(*)
        FROM    TB_HQ_NMCODE
        WHERE   HQ_OFFICE_CD  = #{hqOfficeCd}
        AND     NMCODE_GRP_CD = #{nmcodeGrpCd}
        AND     NMCODE_CD     = #{nmcodeCd}



        SELECT  COUNT(*)
        FROM    TB_MS_STORE_NMCODE
        WHERE   STORE_CD      = #{storeCd}
        AND     NMCODE_GRP_CD = #{nmcodeGrpCd}
        AND     NMCODE_CD     = #{nmcodeCd}

/* USE : CdMapper.getCdStoreAllowDupCnt */
SELECT  COUNT(*)
FROM    TB_HQ_NMCODE
WHERE   HQ_OFFICE_CD   = #{hqOfficeCd}
AND     NMCODE_GRP_CD  = '251'
AND     NMCODE_NM      = #{nmcodeNm}
AND     NMCODE_ITEM_1  = #{nmcodeItem1}

/* USE : CdMapper.getCdStoreAllowMaxCd */
SELECT  TO_CHAR(NVL(MAX(TO_NUMBER(NMCODE_CD)), 0) + 1)
FROM    TB_HQ_NMCODE
WHERE   HQ_OFFICE_CD  = #{hqOfficeCd}
AND     NMCODE_GRP_CD = '251'

/* USE : CdMapper.getCdStoreAllowItem */
SELECT  CASE WHEN INSTR(NVL(MAX(NMCODE_ITEM_2), ' '), 'I') > 0 THEN 'Y' ELSE 'N' END AS I_YN
,       CASE WHEN INSTR(NVL(MAX(NMCODE_ITEM_2), ' '), 'U') > 0 THEN 'Y' ELSE 'N' END AS U_YN
,       CASE WHEN INSTR(NVL(MAX(NMCODE_ITEM_2), ' '), 'D') > 0 THEN 'Y' ELSE 'N' END AS D_YN
FROM    TB_HQ_NMCODE
WHERE   HQ_OFFICE_CD   = #{hqOfficeCd}
AND     NMCODE_GRP_CD  = '251'
AND     NMCODE_NM      = #{nmcodeNm}
AND     NMCODE_ITEM_1  = #{storeCd}

